g.text:
hortest useful loop — create a run with one inline test, then poll:

```bash theme={"theme":"css-variables"}
# 1. Create (r

'{
 "suiteName": "smoke",
 "serverIds": ["'$SERVER_ID'"],
 "tests": [{
 "title": "echo works",

{ "id": "s1", "kind": "prompt", "prompt": "Use the echo tool to say hi" },
 {
 "id": "s2",

echo",
 "args": { "args": { "text": "hi" } }
 }
 }
 ]
 }]
 }' | jq -er .runId)\
